// The prompt every harness sends for a report, and the instructions that explain it. Plain
// ESM with JSDoc types, so the Claude Code mod, the receiver and other harnesses' adapters
// load it without a build.

/**
 * @typedef {import('../types').Accessibility} Accessibility
 * @typedef {import('../types').AxElement} AxElement
 * @typedef {import('../types').FixReport} FixReport
 * @typedef {import('../types').Incoming} Incoming
 */

/** What a `[fix …]` prompt calls for; sent with the system prompt while the mod is loaded. */
export const INSTRUCTIONS = `# Fix requests from the running app

A prompt that ends with a line like

[fix r1] TransactionRow › Text · Features/Home/TransactionRow.swift:29 · used at Features/Home/HomeView.swift:60 · StaticText "−€7.40" near "Coffee" · .fixkit/reports/r1.png
[fix r2] StaticText "+€4,650.00" near "Northwind GmbH", "Salary, September" · Activity screen · .fixkit/reports/r2.png
[fix r3] ProfileViewController.nameLabel · UILabel "Alex Morgan" · .fixkit/reports/r3.png

was sent from the iOS app running in the simulator by the fixkit mod: someone long-pressed an element and typed the text above that line. The line holds the report's id and what is known about the element: in SwiftUI, the view's type after the app's view around it, or after the .fixable("name") on it or on a view around it, the file and line where the view's expression starts, and where the app's views around it are used; what accessibility says it is (its type, label, value, the control around it and the labels beside it in the same row); in a UIKit app, the view named after the property that holds it as Type.property, or its class and text, and its view controller as the screen; the screen's name when the app gives one; and a screenshot with the element outlined in red, or a red ring where the finger was.

When a prompt carries that line:
- Treat the text above it as the request. It may be a bug ("button is shifted") or a change ("make this green").
- With a file and line, start there: the cause is in that view's expression and its modifiers, in the view around it, or in what is passed where that view is used.
- When accessibility names something that is not at that line, something drawn over that view was pressed, such as a bar over a list: go by accessibility and the screenshot.
- With a Type.property name, start at that property's declaration and where it is configured.
- Without one, find the view by searching the Swift sources for the label and the labels beside it; a label made from data (an amount, a date) is found through the view that formats it, so search the neighbouring fixed labels first.
- Make the smallest change that does what was asked. Do not refactor.
- Open the screenshot only when the text and the code leave the request unclear.
- Then rebuild and relaunch the app in the simulator the way this project builds (XcodeBuildMCP's build_run_sim when it is connected), so the change is on screen: the report counts as fixed once the app has launched again.
- Answer in one or two sentences: what was wrong and what changed.`

/** What a `[fix …]` prompt calls for in a React Native project, in place of `INSTRUCTIONS`. */
export const RN_INSTRUCTIONS = `# Fix requests from the running app

A prompt that ends with a line like

[fix r1] WalletCard › Text · src/WalletCard.tsx:18 · used at App.tsx:31 · StaticText "Alex Morgan" · .fixkit/reports/r1.png
[fix r2] StaticText "+€4,650.00" near "Northwind GmbH", "Salary, September" · .fixkit/reports/r2.png

was sent from the React Native app running in the iOS simulator by the fixkit mod: someone long-pressed an element and typed the text above that line. The line holds the report's id and what is known about the element: the components that rendered it, innermost last; the file and line where its JSX is written; where the components around it are used; what accessibility says it is (its type, label, value, #testID, the control around it and the labels beside it in the same row); and a screenshot with the element outlined in red, or a red ring where the finger was.

When a prompt carries that line:
- Treat the text above it as the request. It may be a bug ("button is shifted") or a change ("make this green").
- With a file and line, start there: the cause is on that element, in the component around it, or in the props passed where that component is used. The line is read from the code the app launched with, so when that file has changed since, look around it.
- Without one, find the element by searching the app's .tsx, .ts, .jsx and .js sources for its label, its testID and the labels beside it; a label made from data (an amount, a date) is found through the component that formats it, so search the neighbouring fixed labels first.
- Make the smallest change that does what was asked. Do not refactor.
- Open the screenshot only when the text and the code leave the request unclear.
- Save the change and do not rebuild: Metro's Fast Refresh puts it on screen, which counts the report as fixed. Rebuild only when the change touches native code or native configuration, with the project's own command (npx expo run:ios, npx react-native run-ios).
- Answer in one or two sentences: what was wrong and what changed.`

/**
 * What a `[fix …]` prompt calls for in a Flutter project, in place of `INSTRUCTIONS`, with the way
 * the harness hot reloads the app: `reload` asks for a reload, `restart` for a restart instead.
 * @param {{ reload: string, restart: string }} how
 */
function flutterInstructions({ reload, restart }) {
  return `# Fix requests from the running app

A prompt that ends with a line like

[fix r1] ProfileHeader › Text · lib/profile_header.dart:24 · used at lib/home.dart:31 · StaticText "Alex Morgan" · .fixkit/reports/r1.png
[fix r2] StaticText "+€4,650.00" near "Northwind GmbH", "Salary, September" · .fixkit/reports/r2.png

was sent from the Flutter app running in the iOS simulator by the fixkit mod: someone long-pressed an element and typed the text above that line. The line holds the report's id and what is known about the element: the app's widget around it and the widget itself; the file and line where that widget is constructed; where the widgets around it are used; what accessibility says it is (its type, label, value, the control around it and the labels beside it in the same row); and a screenshot with the element outlined in red, or a red ring where the finger was.

When a prompt carries that line:
- Treat the text above it as the request. It may be a bug ("button is shifted") or a change ("make this green").
- With a file and line, start there: the cause is in that constructor call, in the widget around it, or in what is passed where that widget is used.
- Without one, find the widget by searching the app's .dart sources for its label and the labels beside it; a label made from data (an amount, a date) is found through the widget that formats it, so search the neighbouring fixed labels first.
- Make the smallest change that does what was asked. Do not refactor.
- Open the screenshot only when the text and the code leave the request unclear.
- Save the change and ${reload}: it puts the change on screen, which counts the report as fixed. ${restart} when hot reload does not apply the change: a change to initState, field initializers, global or static variables, main, or an enum or generic type. When it fails, run dart analyze on the files you changed, fix what it reports and call it again. Rebuild with flutter run only when the change touches native code or native configuration.
- Answer in one or two sentences: what was wrong and what changed.`
}

// How Claude Code hot reloads the app: through the hot_reload tool its mod serves.
const CLAUDE_CODE_RELOAD = { reload: 'call the hot_reload tool', restart: 'Pass restart: true' }

/**
 * The instructions for a project of `kind`. A Flutter project's say how this harness hot reloads
 * the app; without `flutterReload`, through the Claude Code mod's hot_reload tool.
 * @param {ProjectKind} kind
 * @param {{ reload: string, restart: string }} [flutterReload]
 */
export function instructionsFor(kind, flutterReload = CLAUDE_CODE_RELOAD) {
  if (kind === 'flutter') return flutterInstructions(flutterReload)
  return kind === 'react-native' ? RN_INSTRUCTIONS : INSTRUCTIONS
}

/** The Flutter instructions for Claude Code, whose mod serves the hot_reload tool. */
export const FLUTTER_INSTRUCTIONS = instructionsFor('flutter')

/** The tool the mod serves in a Flutter project: hot reload, or restart, the app `flutter run` runs. */
export const HOT_RELOAD_TOOL = 'mcp__fixkit__hot_reload'

/** @typedef {'native' | 'react-native' | 'flutter'} ProjectKind */

/**
 * Flutter when pubspec.yaml depends on the Flutter SDK, React Native when package.json depends on it, else native.
 * @param {{ packageJson: string | null, pubspec: string | null }} files
 * @returns {ProjectKind}
 */
export function projectKind({ packageJson, pubspec }) {
  if (pubspec !== null && /^\s+sdk:\s*flutter\s*(?:#.*)?$/m.test(pubspec)) return 'flutter'
  return isReactNativeProject(packageJson) ? 'react-native' : 'native'
}

/**
 * Whether the project's package.json depends on React Native.
 * @param {string | null} packageJson
 */
export function isReactNativeProject(packageJson) {
  if (packageJson === null) return false
  try {
    const { dependencies = {}, devDependencies = {} } = JSON.parse(packageJson)
    return 'react-native' in dependencies || 'react-native' in devDependencies
  } catch {
    return false
  }
}

/**
 * One accessibility element in words: its type, then its label, value and identifier.
 * @param {AxElement} element
 */
function describeOne(element) {
  const parts = [element.type]
  if (element.label) parts.push(JSON.stringify(element.label))
  if (element.value && element.value !== element.label) parts.push(`= ${JSON.stringify(element.value)}`)
  if (element.identifier) parts.push(`#${element.identifier}`)
  return parts.join(' ')
}

/**
 * What accessibility says was pressed, in one phrase for the prompt and the pane.
 * @param {Accessibility} accessibility
 */
export function describeAccessibility({ element, within, nearby }) {
  let text = describeOne(element)
  if (within) text += ` in ${describeOne(within)}`
  if (nearby.length > 0) text += ` near ${nearby.map(label => JSON.stringify(label)).join(', ')}`
  return text
}

/**
 * The prompt: the person's comment as they typed it, then one line of context.
 * `INSTRUCTIONS` tells the model what a message carrying a `[fix …]` line calls for.
 * @param {Incoming} incoming
 * @param {string | null} source
 * @param {string[]} [usedAt]
 */
export function promptFor(incoming, source, usedAt = []) {
  const { comment, element, id, screen, screenshot, touch } = incoming
  const pressed = describePressed(incoming)
  const context = [
    element?.name,
    source,
    usedAt.length > 0 ? `used at ${usedAt.join(', ')}` : null,
    pressed,
    // A marked element says where it is; otherwise the screen's name helps find it.
    !element && screen ? `${screen} screen` : null,
    !element && !pressed && touch ? `touch at ${Math.round(touch.x)},${Math.round(touch.y)}` : null,
    screenshot,
  ].filter(Boolean)

  return `${comment}\n\n[fix ${id}] ${context.join(' · ')}`
}

/**
 * What was pressed in words. A UIKit app describes the very view it found under the finger, so its
 * words come first; accessibility, read by position, can name a view under a sheet or a container.
 * @param {{ accessibility?: Accessibility | null, viewDescription?: string | null }} pressed
 * @returns {string | null}
 */
function describePressed({ accessibility, viewDescription }) {
  return viewDescription ?? (accessibility ? describeAccessibility(accessibility) : null)
}

/**
 * How the pane names what was pressed: the element's name, else what the app or accessibility said.
 * @param {Pick<FixReport, 'element' | 'accessibility' | 'viewDescription' | 'screen'>} report
 */
export function pressedLabel(report) {
  const { element, screen } = report
  if (element) return element
  const pressed = describePressed(report)
  if (pressed) return pressed
  return screen ? `${screen} screen` : 'unnamed element'
}

/**
 * Whether a tool call puts a new build on screen: XcodeBuildMCP's build-and-run, or the mod's own
 * hot reload in a Flutter project. The pane shows the report as rebuilding meanwhile; whether the
 * fix reached the screen comes from the app itself, when it launches or reloads.
 * @param {string} tool
 */
export function isBuildAndRun(tool) {
  return tool === HOT_RELOAD_TOOL || /(?:^|_)build_run_sim$/.test(tool)
}

